plugins {
    alias(libs.plugins.kotlin.jvm)
    `maven-publish`
}

// The token file is generated (packages/tokens/scripts/build-tokens.mjs) and is the only source here.
java {
    sourceCompatibility = JavaVersion.VERSION_17
    targetCompatibility = JavaVersion.VERSION_17
}

kotlin {
    explicitApi()
    compilerOptions {
        jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17)
    }
}

// The brand engine tests read the shared fixture generated by the token build.
val brandFixture = rootProject.file("../../packages/tokens/generated/json/brand-fixture.json")

tasks.withType<Test>().configureEach {
    inputs.file(brandFixture).withPropertyName("brandFixture").optional()
    systemProperty("stance.brandFixture", brandFixture.absolutePath)
}

dependencies {
    testImplementation(libs.kotlin.test)
    testImplementation(libs.junit)
}

publishing {
    publications {
        create<MavenPublication>("maven") {
            from(components["java"])
            artifactId = "stance-tokens"
            pom {
                name.set("Stance Tokens")
                description.set("Design tokens for Stance, the Binds design system.")
                url.set("https://www.stanceui.com")
                licenses { license { name.set("Apache-2.0"); url.set("https://www.apache.org/licenses/LICENSE-2.0") } }
            }
        }
    }
    repositories { maven { name = "localTest"; url = uri(rootProject.layout.buildDirectory.dir("repo")) } }
}
